package main

import (
	"fmt"
	"runtime"
	"sync"
	"time"
)

type result struct{ job, square int }

func run(workers int) <-chan result {
	jobs := make(chan int)
	results := make(chan result)
	var wg sync.WaitGroup
	for w := 1; w <= workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for n := range jobs {
				results <- result{n, n * n}
			}
		}()
	}
	go func() {
		for n := 1; n <= 9; n++ {
			jobs <- n
		}
		close(jobs)
	}()
	go func() { wg.Wait(); close(results) }()
	return results
}

func main() {
	results := run(3)
	<-results
	time.Sleep(200 * time.Millisecond)
	fmt.Println("goroutines alive:", runtime.NumGoroutine())
}

package main

import (
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

func main() {
	var calls atomic.Int64
	deadline := time.Now().Add(1100 * time.Millisecond)
	var wg sync.WaitGroup
	for w := 1; w <= 4; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			ticker := time.NewTicker(200 * time.Millisecond)
			defer ticker.Stop()
			for time.Now().Before(deadline) {
				<-ticker.C
				if time.Now().Before(deadline) {
					calls.Add(1)
				}
			}
		}()
	}
	wg.Wait()
	fmt.Println("calls in 1.1 s:", calls.Load())
}
